visualizations.logic:
var billionsOfSar = variables.billionsOfSar;
var tesseract = variables.tesseract;
var id = variables.id;
var quarters = variables.quarters;
var years = variables.years;
var nameUpper = variables.nameUpper;
var name = variables.name;
var pctChart = formatters.pctChart;
var commas = formatters.commas;
var abbreviate = formatters.abbreviate;
var decimal = formatters.decimal;
var pctDecimal = formatters.pctDecimal;

var time = "quarterOption" //yearOption, quarterOption
var timeName = "التطوّر ربع السنوي"

var timeID = time === "yearOption" ? "Year" : "Quarter ID"
var timeCut = time === "yearOption" ? "Year" : "Quarter"
var cube = time === "yearOption" ? "_year" : ""

var measures = "value"//value, shareGdp, growthRate

  var realMeasure = measures === "value" ? "Real+GDP" : measures === "shareGdp" ? "Real+GDP+Share" : (time === "yearOption" ? "Real+GDP+Growth+Rate" : "Real+GDP+Growth+Rate+(YoY)")
var nominalMeasure = measures === "value" ? "Nominal+GDP" : measures === "shareGdp" ? "Nominal+GDP+Share" : "Nominal+GDP+Growth+Rate"
var seasonallyMeasure = measures === "value" ? "Seasonally+Adjusted+Real+GDP" : measures === "shareGdp" ? "Seasonally+Adjusted+Real+GDP+Share" : "Seasonally+Adjusted+Real+GDP+Growth+Rate"

var real = tesseract + "/data.jsonrecords?Economic+Sectors=" + id + "&cube=gastat_real_gdp_by_economic_activity" + cube + "&drilldowns=" + timeCut + "&measures=" + realMeasure + "&locale=" + locale
var nominal = tesseract + "/data.jsonrecords?Economic+Sectors=" + id + "&cube=gastat_nominal_gdp_by_economic_activity" + cube + "&drilldowns=" + timeCut + "&measures=" + nominalMeasure + "&locale=" + locale
var seasonally = tesseract + "/data.jsonrecords?Economic+Sectors=" + id + "&cube=gastat_seasonally_adjusted_real_gdp_by_economic_activity" + cube + "&drilldowns=" + timeCut + "&measures=" + seasonallyMeasure + "&locale=" + locale

var translations = {
title: { 
    value: {en: (timeName + " Evolution of Real, Nominal and Seasonally Adjusted Real GDP in the " + nameUpper + " Sector"), ar: (" " + timeName + " في قيمة الناتج المحلي الإجمالي الحقيقي، والاسمي، والمعدل موسميًا في قطاع " + name)},
    shareGdp: {en: (timeName + " Evolution of the Share of Real, Nominal and Seasonally Adjusted Real GDP in the " + nameUpper + " Sector"), ar: (timeName + " في حصة قطاع " + name + " من الناتج المحلي الإجمالي الحقيقي، والاسمي، والمعدل موسميًا")},
    growthRate: {en: (timeName + " Evolution of the Growth Rate of Real, Nominal and Seasonally Adjusted Real GDP in the " + nameUpper + " Sector (YoY Growth)"), ar:  (timeName + " في معدل نمو الناتج المحلي الإجمالي الحقيقي، والاسمي، والمعدل موسميًا في قطاع " + name)},
  },

  quarter: {en: "Quarter", ar: "الربع"},
  year: {en: "Year", ar: "سنة"},
  real: {en: "Real GDP", ar: "الحقيقي"},
  nominal: {en: "Nominal GDP", ar: "الاسمي"},
  seasonally: {en: "Seasonally adjusted real GDP", ar: "المعدل موسميًا"},
  value: {en: "Value", ar: "القيمة"},
  category: {en: "Category", ar: "الفئة"},
  share: {en: "Share in Total GDP", ar: "الحصة في الناتج المحلي الإجمالي"},
  growth: {en: "Growth Rate", ar: "معدل النمو"}
}

var metric = measures === "value" ? 1000000 : measures === "shareGdp" ? 100 : 100
var scaleFactor = measures === "value" ? 1000000000 : 1
var formatter = measures === "value" ? decimal : pctDecimal;
var tooltip = measures === "value" ? ((translations["value"][locale]) + " (" + billionsOfSar + ")") : measures === "shareGdp" ? ("" + (translations["share"][locale])) : ("" + (translations["growth"][locale]))
var timeTranslation = time === "yearOption" ? ("" + (translations["year"][locale])) : ("" + (translations["quarter"][locale]))

var measureName = measures === "value" ? ("" + (translations["value"][locale])) : measures === "shareGdp" ? ("" + (translations["share"][locale])) : ("" + (translations["growth"][locale]))

return {
  axisPersist: false,
  data: [real, nominal, seasonally],
  dataFormat: function (resp) {
    var real_ = resp[0].data;
    var nominal_ = resp[1].data;
    var seasonally_ = resp[2].data;

    var updateData = function (data, category, categoryID, value) {
      data.forEach(function (d) {
        d["GDP Type ID"] = categoryID;
        d["GDP Type"] = category;
        d["Value"] = d[value] != null ? d[value] * metric : null
      });
      return data;
    };

    real_ = updateData(real_, ("" + (translations["real"][locale])), 1, realMeasure.replace(/\+/g, " "));
    nominal_ = updateData(nominal_, ("" + (translations["nominal"][locale])), 2, nominalMeasure.replace(/\+/g, " "));
    seasonally_ = updateData(seasonally_, ("" + (translations["seasonally"][locale])), 3, seasonallyMeasure.replace(/\+/g, " "));

    var dataFinal = real_.concat(nominal_.concat( seasonally_))

    return measures === "growthRate"
      ? dataFinal.filter(function (d) { return d["Value"] != null; })
      : dataFinal;
  },

  viewDataFormat: function (resp) {
    var real_ = resp[0].data;
    var nominal_ = resp[1].data;
    var seasonally_ = resp[2].data;

    var updateData = function (data, category, categoryID, value) {
      data.forEach(function (d) {
        d["GDP Type ID"] = categoryID;
        d["GDP Type"] = category;
        d["Value"] = d[value] != null ? d[value] * metric : null
      });
      return data;
    };

    real_ = updateData(real_, ("" + (translations["real"][locale])), 1, realMeasure.replace(/\+/g, " "));
    nominal_ = updateData(nominal_, ("" + (translations["nominal"][locale])), 2, nominalMeasure.replace(/\+/g, " "));
    seasonally_ = updateData(seasonally_, ("" + (translations["seasonally"][locale])), 3, seasonallyMeasure.replace(/\+/g, " "));

    var dataFinal = real_.concat(nominal_.concat( seasonally_))

    return dataFinal.map(function (d) {
      var obj;

      return (( obj = {}, obj[("" + timeTranslation)] = d[timeCut], obj[("" + (translations["category"][locale]))] = d["GDP Type"], obj[("" + measureName)] = d.Value, obj ));
    })
  },
  groupBy: ["GDP Type ID"],
  label: function (d) { return ""; },
  legendConfig: {
    label: function (d) { return d["GDP Type"]; }
  },
  legendSort: function (a,b) { return b["GDP Type ID"] - a["GDP Type ID"]; },
  legendPosition: "bottom",
  legendTooltip: {
    tbody: false,
  },
  lineLabels: false,
  shapeConfig: {
    Line: {
      label: function label(d) {
        var dataArray = this._filteredData
          	.filter(function (f) { return f["GDP Type"] === d["GDP Type"]; });
        var maxX = Math.max.apply(Math, dataArray.map(function (f) { return f[timeID]; }));			
        var maxData = dataArray
        	.find(function (f) { return f[timeID] === maxX; });

        return ("" + (formatter(maxData["Value"]/scaleFactor)));
      },
    }
  },
  time: timeCut,
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  tooltipConfig: {
    tbody: [
      [("" + timeTranslation), function (d) { return time == 'quarterOption' ? formatters.quarterTooltip(d[timeCut]) : d[timeCut]; }],
      [("" + tooltip), function (d) { return formatter(d["Value"] / scaleFactor); }]
    ]
  },
  title: ("" + (translations["title"][measures][locale])),
  type: "LinePlot",
  x: timeCut,
  xConfig: {
    title: time === "yearOption" ? years : quarters,
  },
  y: "Value",
  yConfig: {
    title: measures === "value" ? billionsOfSar : measures === "shareGdp" ? ("" + (translations["share"][locale])) : ("" + (translations["growth"][locale])),
    tickFormat: function (d) { return measures === "value" ? commas(d / scaleFactor) : pctChart(d / scaleFactor); }
  }
}

var tesseract = variables.tesseract;
var id = variables.id;
var millionsOfSar = variables.millionsOfSar;
var thousandsOfSar = variables.thousandsOfSar;
var months = variables.months;
var nameUpper = variables.nameUpper;
var name = variables.name;
var decimal = formatters.decimal;
var commas = formatters.commas;

var selector = "value" //value, volume
var selectorName = "القيمة"

var measure = selector === "value" ? "Value" : "Volume"

var translations = {
    month: {en: "Month", ar: "الشهر"},
  title: {
    value: {en: ("Monthly Evolution of the SADAD System Payments Value in the " + nameUpper + " Sector"), ar: ("التطور الشهري في قيمة المدفوعات المنفّذة عبر نظام سداد في قطاع " + name)},
    volume: {en: ("Monthly Evolution of the SADAD System Payments Volume in the " + nameUpper + " Sector"), ar: ("التطور الشهري في عدد المدفوعات المنفّذة عبر نظام سداد في قطاع " + name)}
  },
  billion: {en: "Billions", ar: "مليار"},
  million: {en: "Millions", ar: "مليون"},
  value : {en: "System Payment Value", ar: "قيمة مدفوعات سداد"},
  volume : {en: "System Payment Volume", ar: "عدد مدفوعات سداد"},
  volume_: {en: "Volume", ar: "العدد"},
}
var valueTooltip = millionsOfSar//["H", "P", "R", "S"].includes(id) ? thousandsOfSar : millionsOfSar
var volumeTooltip = "" + (translations["million"][locale])//["H", "P", "R", "S"].includes(id) ? `${translations["million"][locale]}` : `${translations["billion"][locale]}`
var scaleFactorName = selector === "value" ? valueTooltip : volumeTooltip
var yAxisName = selector === "value" ? ((translations["value"][locale]) + " (" + valueTooltip + ")") : ((translations["volume_"][locale]) + " (" + volumeTooltip + ")")

var valueFactor = 1000000//["H", "P", "R", "S"].includes(id) ? 1000 : 1000000
var volumeFactor = 1000000//["H", "P", "R", "S"].includes(id) ? 1000000 : 1000000000
var scaleFactor = selector === "value" ? valueFactor : volumeFactor

var factor = selector === "value" ? 1000 : 1
var tooltip = selector === "value" ? ((translations["value"][locale]) + " (" + valueTooltip + ")") : ((translations["volume"][locale]) + " (" + volumeTooltip + ")")

return {
  axisPersist: false,
  cache: false,
  data: (tesseract + "/data.jsonrecords?Economic+Sectors=" + id + "&cube=sama_volume_value_sector&drilldowns=Economic+Sectors,Month&measures=" + measure + "&locale=" + locale),
  dataFormat: function (resp) {
    var data = resp.data;

    data.forEach(function (d) {
      d[measure] = d[measure] * factor
      d.Month = (d["Month"]) + "-01 00:00:00";
    })

    return data;
  },
  viewDataFormat: function (resp) {
    var data = resp.data;

    data.forEach(function (d) {
      d[measure] = d[measure] * factor
    })

    return data.map(function (d) {
      var obj;

      return (( obj = {}, obj[("" + (translations["month"][locale]))] = formatters.formatMonth(d["Month ID"]), obj[("" + tooltip)] = d[measure], obj ));
    })
  },
  groupBy: ["Economic Sectors ID"],
  label: function (d) { return ""; },
  lineLabels: true,
  shapeConfig: {
    Line: {
      label: function label(d) {
        var dataArray = this._filteredData
          	.filter(function (f) { return f["Economic Sectors ID"] === d["Economic Sectors ID"]; });
        var maxX = Math.max.apply(Math, dataArray.map(function (f) { return f["Month ID"]; }));			
        var maxData = dataArray
        	.find(function (f) { return f["Month ID"] === maxX; });

        return ("" + (decimal(maxData[measure]/scaleFactor)));
      },
    }
  },
  time: "Month",
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  title: ("" + (translations["title"][selector][locale])),
  tooltipConfig: {
    title: function (d) { return tooltip; },
    tbody: [
      [("" + (translations["month"][locale])), function (d) { return formatters.formatMonth(d["Month ID"]); }],
      [(selectorName + " (" + scaleFactorName + ")"), function (d) { return decimal(d[measure]/scaleFactor); }]
    ]
  },
  type: "LinePlot",
  x: "Month",
  xConfig: {
    title: months
  },
  y: measure,
  yConfig: {
    //title: yAxisName,
    title: millionsOfSar,
    tickFormat: function (d) { return (d%scaleFactor===0) ? commas(d/scaleFactor) : decimal(d/scaleFactor); }
  }
};

var tesseract = variables.tesseract;
var id = variables.id;
var billionsOfSar = variables.billionsOfSar;
var months = variables.months;
var years = variables.years;
var nameUpper = variables.nameUpper;
var name = variables.name;
var commas = formatters.commas;
var abbreviate = formatters.abbreviate;
var lowercase = formatters.lowercase;
var decimal = formatters.decimal;
var pctChart = formatters.pctChart;
var pctDecimal = formatters.pctDecimal;

var translations = {
  Month: {en: "Month", ar: "الشهر"},
  Year: {en: "Month", ar: "السنة"},
  titleMonthValue: {en: ("Monthly Evolution of Commercial Bank Credits in the " + name + " Sector"), ar: ("التطوّر الشهري في قيمة الائتمان المصرفي في قطاع " + name)},
  titleYearValue: {en: ("Annual Evolution of Commercial Bank Credits in the " + name + " Sector"), ar: ("التطوّر السنوي في قيمة الائتمان المصرفي في قطاع " + name)},
  titleMonthGrowth: {en: ("Monthly YoY Growth Rate of Commercial Bank Credits in the " + name + " Sector"), ar: ("معدل النمو السنوي للائتمان المصرفي في قطاع " + name)},
  titleYearGrowth: {en: ("Annual Growth Rate of Commercial Bank Credits in the " + name + " Sector"), ar: ("معدل النمو السنوي للائتمان المصرفي في قطاع " + name)},
  credits: {en: "Commercial Bank Credit", ar: "الائتمان المصرفي"}, 
  growth: {en: "Growth Rate", ar: "معدل النمو"}
}

var timeSelector = "monthOption" // yearOption, monthOption
var metricSelector = "value" // value, growthRateYoY 

var time = timeSelector === "yearOption" ? "Year" : "Month"
var timeID = timeSelector === "yearOption" ? "Year" : "Month ID"
var metric = metricSelector === "value" ? "Bank Credit" : "Growth Rate"

var scaleFactor = metricSelector === "value" ? 1000000000 : 1
var formatter = metricSelector === "value" ? decimal : pctDecimal

var title = ""
if(timeSelector === "monthOption" && metricSelector === "value"){
  title = "" + (translations["titleMonthValue"][locale])
}
else if(timeSelector === "yearOption" && metricSelector === "value"){
  title = "" + (translations["titleYearValue"][locale])
}
else if(timeSelector === "monthOption" && metricSelector !== "value"){
  title = "" + (translations["titleMonthGrowth"][locale])
}
else{
  title = "" + (translations["titleYearGrowth"][locale])
}

return {
  axisPersist: false,
  cache: false,
  data: (tesseract + "/data.jsonrecords?Economic+Sectors=" + id + "&cube=sama_commercial_bank_credit_economic_activity&drilldowns=Economic+Sectors,Month,Year&measures=Bank+Credit&locale=" + locale),
  dataFormat: function (resp) {
    var data = resp.data;

    data.forEach(function (d) {
        d["Bank Credit"] = d["Bank Credit"] * 1000000
        d.Month = (d["Month"]) + "-01 00:00:00";
      })

    if(timeSelector === "monthOption"){
      data.forEach(function (d, index) {
        var s = data.slice(0, index).find(function (h) { return (h["Month ID"] * 1 === d["Month ID"] * 1 - 100); }) || {};
        d["Value Prev"] = s["Bank Credit"];
        d["Growth"] = d["Bank Credit"] - d["Value Prev"];
        d["Growth Rate"] = ((d["Bank Credit"] - d["Value Prev"]) / d["Value Prev"]) * 100;
        delete d["Growth"]
        delete d["Value Prev"]
      });
    }

    else {
        data = data.filter(function (d) { return ("" + (d["Month ID"])).slice(-2) === "12"; })

        data.forEach(function (d, index) {
          var s = data.slice(0, index).find(function (h) { return (h["Year"] * 1 === d["Year"] * 1 - 1); }) || {};
          d["Value Prev"] = s["Bank Credit"];
          d["Growth"] = d["Bank Credit"] - d["Value Prev"];
          d["Growth Rate"] = ((d["Bank Credit"] - d["Value Prev"]) / d["Value Prev"]) * 100;
          delete d["Growth"]
          delete d["Value Prev"]
        });
    }

    var dataFinal = metricSelector === "value" ? data : data.filter(function (d) { return d["Growth Rate"]; })
    return dataFinal;
  },
  viewDataFormat: function (resp) {
    var data = resp.data;

    data.forEach(function (d) {
        d["Bank Credit"] = d["Bank Credit"] * 1000000
        d.Month = d["Month"].replace(/-/g, "/");
      })

    if(timeSelector === "monthOption"){
      data.forEach(function (d, index) {
        var s = data.slice(0, index).find(function (h) { return (h["Month ID"] * 1 === d["Month ID"] * 1 - 100); }) || {};
        d["Value Prev"] = s["Bank Credit"];
        d["Growth"] = d["Bank Credit"] - d["Value Prev"];
        d["Growth Rate"] = ((d["Bank Credit"] - d["Value Prev"]) / d["Value Prev"]) * 100;
        delete d["Growth"]
        delete d["Value Prev"]
      });
    }

    else {
        data = data.filter(function (d) { return ("" + (d["Month ID"])).slice(-2) === "12"; })

        data.forEach(function (d, index) {
          var s = data.slice(0, index).find(function (h) { return (h["Year"] * 1 === d["Year"] * 1 - 1); }) || {};
          d["Value Prev"] = s["Bank Credit"];
          d["Growth"] = d["Bank Credit"] - d["Value Prev"];
          d["Growth Rate"] = ((d["Bank Credit"] - d["Value Prev"]) / d["Value Prev"]) * 100;
          delete d["Growth"]
          delete d["Value Prev"]
        });
    }

    var dataFinal = metricSelector === "value" ? data : data.filter(function (d) { return d["Growth Rate"]; })

    return dataFinal.map(function (d) {
      var obj;

      return (( obj = {}, obj[("" + (translations[time][locale]))] = d[time], obj[("" + (translations["credits"][locale]))] = d["Bank Credit"], obj[("" + (translations["growth"][locale]))] = d["Growth Rate"], obj ));
    })
  },
  groupBy: ["Economic Sectors ID"],
  label: function (d) { return ""; },
  lineLabels: true,
  shapeConfig: {
    Line: {
      label: function label(d) {
        var dataArray = this._filteredData
          	.filter(function (f) { return f["Economic Sectors ID"] === d["Economic Sectors ID"]; });
        var maxX = Math.max.apply(Math, dataArray.map(function (f) { return f[timeID]; }));			
        var maxData = dataArray
        	.find(function (f) { return f[timeID] === maxX; });

        return ("" + (formatter(maxData[metric]/scaleFactor)));
      },
    }
  },
  time: time,
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  title: title,
  tooltipConfig: {
    title: function (d) { return metricSelector === "value" ? ("" + (translations["credits"][locale])) : ("" + (translations["growth"][locale])); },
    tbody: function (d) {
      var customTooltip = [];
      metricSelector === "value" ?
        customTooltip = [
          [("" + (translations[time][locale])), time === "Month" ? formatters.formatMonth(d["Month ID"]) : d[time]],
          [((translations["credits"][locale]) + " (" + billionsOfSar + ")"), decimal(d["Bank Credit"]/scaleFactor)] ]
        :
        customTooltip = [
          [("" + (translations[time][locale])), time === "Month" ? formatters.formatMonth(d["Month ID"]) : d[time]],
          [("" + (translations["growth"][locale])), pctDecimal(d["Growth Rate"])]
        ]
      return customTooltip;
    },
  },
  type: "LinePlot",
  x: time,
  xConfig: {
    title: timeSelector === "monthOption" ? months : years
  },
  y: metric,
  yConfig: {
    //title: metricSelector !== "growthRateYoY" ? `${translations["credits"][locale]} (${billionsOfSar})` : `${translations["growth"][locale]}`,
    title: metricSelector !== "growthRateYoY" ? ("" + billionsOfSar) : ("" + (translations["growth"][locale])),
    tickFormat: function (d) { return metricSelector === "growthRateYoY" ? pctChart(d) : ((d%scaleFactor === 0) ? commas(d/scaleFactor) : decimal(d/scaleFactor)); }
  }
};

var tesseract = variables.tesseract;
var id = variables.id;
var billionsOfSar = variables.billionsOfSar;
var millionsOfSar = variables.millionsOfSar;
var quarters = variables.quarters;
var years = variables.years;
var nameUpper = variables.nameUpper;
var name = variables.name;
var commas = formatters.commas;
var decimal = formatters.decimal;
var lowercase = formatters.lowercase;
var pctChart = formatters.pctChart;
var pctDecimal = formatters.pctDecimal;
 
var translations = {
  Quarter: {en: "Quarter", ar: "الربع"},
  Year: {en: "Year", ar: "السنة"},
  titleQuarterValue: {en: ("Quarterly Evolution of the Finance Companies' Credit to Non-Retail in the " + nameUpper + " Sector"), ar: ("التطوّر ربع السنوي للائتمان الممنوح من شركات التمويل لغير الأفراد في قطاع " + name)},
  titleYearValue: {en: ("Annual Evolution of the Finance Companies' Credit to Non-Retail in the " + nameUpper + " Sector"), ar: ("التطوّر السنوي للائتمان الممنوح من شركات التمويل لغير الأفراد في قطاع " + name)},
  titleQuarterGrowth: {en: ("Quarterly YoY Growth Rate of Finance Companies' Credit to Non-Retail in the " + nameUpper + " Sector"), ar: ("معدل النمو ربع السنوي للائتمان الممنوح من شركات التمويل لغير الأفراد في قطاع " + name)},
  titleYearGrowth: {en: ("Annual Growth Rate of Finance Companies' Credit to Non-Retail in the " + nameUpper + " Sector"), ar: ("معدل النمو السنوي للائتمان الممنوح من شركات التمويل لغير الأفراد في قطاع " + name)},
 credits: {en: "Finance Companies Credit", ar: "قيمة الائتمان"},
  growth: {en: "Growth Rate", ar: "معدل النمو"}
}

var titleName = (translations["credits"][locale]) + " (" + millionsOfSar + ")"//["C", "F", "G", "S"].includes(id) ? billionsOfSar : millionsOfSar

var timeSelector = "yearOption"
var metricSelector = "value"

var time = timeSelector === "yearOption" ? "Year" : "Quarter"
var timeID = timeSelector === "yearOption" ? "Year" : "Quarter ID"
var metric = metricSelector === "value" ? "Finance Companies' Credit" : "Growth Rate"

//const scaleFactorValue = ["C", "F", "G", "S"].includes(id) ? 1000000000 : 1000000
var scaleFactor = metricSelector === "value" ? 1000000 : 1

var formatter = metricSelector === "value" ? decimal : pctDecimal;

var title = ""
if(timeSelector === "quarterOption" && metricSelector === "value"){
  title = "" + (translations["titleQuarterValue"][locale])
}
else if(timeSelector === "yearOption" && metricSelector === "value"){
  title = "" + (translations["titleYearValue"][locale])
}
else if(timeSelector === "quarterOption" && metricSelector !== "value"){
  title = "" + (translations["titleQuarterGrowth"][locale])
}
else{
  title = "" + (translations["titleYearGrowth"][locale])
}

return {
  axisPersist: false,
  cache: false,
  data: (tesseract + "/data.jsonrecords?Economic+Sectors=" + id + "&cube=sama_finance_credit_non_retail_economic_activity&drilldowns=Economic+Sectors,Quarter,Year&measures=Finance+Companies%27+Credit&locale=" + locale),
  dataFormat: function (resp) {
    var data = resp.data;
    
    data.forEach(function (d) {
        d["Finance Companies' Credit"] = d["Finance Companies' Credit"] * 1000000
      })
    
    if(timeSelector === "quarterOption"){
