const {tesseract, id, lastYearAvailableExports, lastYearAvailableImports, nameUpper, name, billionsOfSar, millionsOfSar}  = variables;
const {sar, pctDecimal, decimal} = formatters;
const {nest, sum} = libs.d3;

const time = "[[timeTrade]]"//yearOption, monthOption
const timeName = "{{[[timeTrade]]}}"
const timeOption = time === "yearOption" ? "Year" : "Month"

const flow = "[[tradeFlow]]"//imports, exports
const flowName = "{{[[tradeFlow]]}}"

const sumVariable = flow === "imports" ? "Imports value" : "Exports value"

const dataExports = `${tesseract}/data.jsonrecords?Economic+Sectors=${id}&cube=gastat_exports_value_by_isic_country&drilldowns=Economic+Sectors,Month,Year,Countries,Continent&measures=Exports+value&parents=false&locale=${locale}&a=${time}`
const dataImports = `${tesseract}/data.jsonrecords?Economic+Sectors=${id}&cube=gastat_imports_value_by_isic_country&drilldowns=Economic+Sectors,Month,Year,Countries,Continent&measures=Imports+value&parents=false&locale=${locale}&a=${time}`
const dataURL = flow === "imports" ? dataImports : dataExports

const lastYearAvailable = flow === "exports" ? lastYearAvailableExports : lastYearAvailableImports

const translations = {
  tradeFlow: {en: "Trade Flow", ar: "التدفق التجاري"},
  country: {en: "Country", ar: "الدولة"},
  gastat_exports: {
    en: "GASTAT (Exports)",
    ar: "الهيئة العامة للإحصاء (الصادرات)"
  },
  gastat_imports: {
    en: "GASTAT (Imports)",
    ar: "الهيئة العامة للإحصاء (الواردات)"
  },
  year: {en: "Year", ar: "السنة"},
  month: {en: "Month", ar: "الشهر"},
  title: {
    imports: {
      yearOption: {en: `Imports Value by Country Annually`, ar: `قيمة الواردات حسب الدولة سنويًا`},
      monthOption: {en: `Imports Value by Country Monthly`, ar: `قيمة الواردات حسب الدولة شهريًا`}
    },
    exports: {
      yearOption: {en: `Exports Value by Country Annually`, ar: `قيمة الصادرات حسب الدولة سنويًا`},
      monthOption: {en: `Exports Value by Country Monthly`, ar: `قيمة الصادرات حسب الدولة شهريًا`}
    }
  }
}

const timeTooltip = time === "yearOption" ? `${translations["year"][locale]}` : `${translations["month"][locale]}`

return {
  cache: false,
  axisPersist: false,
  data: dataURL,
  dataFormat: resp => {
    let data = resp.data.filter(d => d["Continent ID"] !== "xx").map(d => Object.assign({}, d))

    data.forEach(d => {
      d["Million SAR"] = d[sumVariable] * 1000000;
      d.Month = `${d["Month"]}-01 00:00:00`;
    });

    const lastMonth = libs.d3.max(data, d => d["Month ID"]).toString().slice(-2)
    const lastYear = libs.d3.max(data, d => d["Month ID"]).toString().slice(0,4)

    const currYear = new Date().getFullYear()
    const cutYear = lastMonth === "12" ? lastYear : (lastMonth !== 12 && lastYearAvailable !== lastYear) ? lastYear : lastYear - 1

    const dataFinal = time === "yearOption" ? data.filter(d => d["Year"] <= cutYear) : data

    nest()
    .key(d => d[timeOption])
    .entries(data)
    .forEach(group => {
      const total = sum(group.values, d => d["Million SAR"])
      group.values.forEach(d => {
        d["Share"] = (d["Million SAR"] / total) * 100
      })
    });

    return dataFinal;
  },
  viewDataFormat: resp => {
     let data = resp.data.map(d => Object.assign({}, d))
    data.forEach(d => {
      d["Million SAR"] = d[sumVariable] * 1000000;
      d.Month = d["Month"].replace(/-/g, "/");
    });

    if(data.length > 0){
      return data.map(d => ({
        [`${translations["year"][locale]}`]: d.Year,
        [`${translations["month"][locale]}`]: d.Month,
        [`${translations["country"][locale]}`]: d.Countries,
        [flowName]: d["Million SAR"],
      }))
    }
    else{
      return [
        {
          [`${translations["year"][locale]}`]: "N/A",
          [`${translations["month"][locale]}`]: "N/A",
          [`${translations["country"][locale]}`]: "No data",
        }
      ];
    }
  },
  sourceFormat: () => {
    return [
      {
        source_name: translations.gastat_exports[locale],
        source_link: "https://database.stats.gov.sa/home/indicator/448"
      },
      {
        source_name: translations.gastat_imports[locale],
        source_link: "https://database.stats.gov.sa/home/indicator/452"
      },
    ]
  },
  groupBy: ["Continent ID", "Countries ID"],
  label: d => String(d["Countries"]),
  legendConfig: {
    label: d => d["Continent"]
  },
  legendPosition: "bottom",
  legendTooltip: {
   title: d => d["Continent"],
   tbody: false,
  },
  shapeConfig: {
    Rect: {
      label: (d, i, x) => [
        d["Countries"],
        [formatters.pctDecimal(d.Share)]
      ],
    }
  },
  sum: "Million SAR",
  threshold: false,
  time: timeOption,
  timeline: true,
  timelineConfig: {
    brushing: false,
    playButton: true
  },
  title: `${translations["title"][flow][time][locale]}`,
  tooltipConfig: {
    title: d => d["Countries"],
    tbody: [
      [timeTooltip, d => timeOption === "Month" ? formatters.formatMonth(d["Month ID"]) :d[timeOption]],
      [`${flowName} (${millionsOfSar})`, d => decimal(d["Million SAR"]/1000000)]
    ]
  },
  type: "Treemap"
};

