    expenses_ = updateData(expenses_, `${translations["expenses"][locale]}`, 2, "Value");
    surplus_ = updateData(surplus_, `${translations["surplus"][locale]}`, 3, "Value");

    let dataFinal = revenues_.concat([...expenses_, ...surplus_])
    
    return dataFinal.map(d => ({
