  time: "Year",
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: true
  },
  tooltipConfig: {
    title: d => d["Revenue Expense"],
    tbody: [
      [`${translations["year"][locale]}`, d => d["Year"]],
      [`${translations["value"][locale]} (${billionsOfSar})`, d => d["Group"] === "Line" ? decimal(d["Value_"] / scaleFactor) : decimal(Math.abs(d["Value_"] / scaleFactor))]
