const selectorName = "{{[[posOptions]]}}"

const measure = selector === "posValue" ? "Sales" : "Number of Transactions"

const translations = {
  month: {en: "Month", ar: "الشهر"},
  title: {
    posValue: {en: `Monthly Evolution of the Value of Points of Sale Transactions in the ${nameUpper} Sector`, ar: `التطوّر الشهري في قيمة عمليات نقاط البيع في قطاع ${name}`},
    posNumber: {en: `Monthly Evolution of the Number of Points of Sale Transactions in the ${nameUpper} Sector`, ar: `التطوّر الشهري في عدد عمليات نقاط البيع في قطاع ${name}`},
