  numberPOS: {en: "Number of POS", ar: "العدد"},
  million: {en: "Millions", ar: "مليون"},
}

const scaleFactorName = (selector === "posValue" && id !== "J") ? billionsOfSar : (selector === "posValue" && id === "J") ? millionsOfSar : `${translations["million"][locale]}`
const yAxisName = (selector === "posValue" && id !== "J") ? `${translations["valuePOS"][locale]} (${billionsOfSar})` : (selector === "posValue" && id === "J") ? `${translations["valuePOS"][locale]} (${millionsOfSar})` : `${translations["numberPOS"][locale]} (${translations["million"][locale]})`
