return {
  axisPersist: false,
  cache: false,
  data: `${tesseract}/data.jsonrecords?Economic+Sectors=${id}&cube=sama_pos_sectors&drilldowns=Month,Economic+Sectors&measures=${measure}&locale=${locale}`,
  dataFormat: resp => {
    let data = resp.data;
    
    data.forEach(d => {
      d[measure] = d[measure] * 1000
      d["Month"] = `${d["Month"]}-01 00:00:00`;
    })
    
    return data;
  },
  viewDataFormat: resp => {
    let data = resp.data;
    
    data.forEach(d => {
      d[measure] = d[measure] * 1000
    })
    
    return data.map(d => ({
      [`${translations["month"][locale]}`]: d.Month,
      [`${tooltipName}`]: d[measure],
    }))
  },
  groupBy: ["Economic Sectors ID"],
  label: d => "",
  lineLabels: true,
  shapeConfig: {
    Line: {
      label(d) {
        const dataArray = this._filteredData.filter(f => f["Economic Sectors ID"] === d["Economic Sectors ID"]);
        const maxX = Math.max(...dataArray.map(f => f["Month ID"]));			
        const maxData = dataArray.find(f => f["Month ID"] === maxX);
        return `${(maxData[measure]/scaleFactor).toFixed(1)}` //. `${decimal(maxData[measure]/scaleFactor)}`;
      },
    }
  },
  time: "Month",
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  title: `${translations["title"][selector][locale]}`,
  tooltipConfig: {
    title: d => selectorName,
    tbody: [
      [`${translations["month"][locale]}`, d => formatters.formatMonth(d["Month ID"])],
      [`${tooltipName} (${scaleFactorName})`, d => decimal(d[measure]/scaleFactor)]
    ]
  },
  type: "LinePlot",
  x: "Month",
  xConfig: {
    title: months
  },
  y: measure,
  yConfig: {
    title: yAxisName,
    tickFormat: d => (d%scaleFactor===0) ? commas(d/scaleFactor) : decimal(d/scaleFactor)
  }
};

