        d["Growth"] = d["Bank Credit"] - d["Value Prev"];
        d["Growth Rate"] = ((d["Bank Credit"] - d["Value Prev"]) / d["Value Prev"]) * 100;
        delete d["Growth"]
        delete d["Value Prev"]
      });
    }

    else {
        data = data.filter(d => `${d["Month ID"]}`.slice(-2) === "12")

        data.forEach((d, index) => {
          const s = data.slice(0, index).find(h => (h["Year"] * 1 === d["Year"] * 1 - 1)) || {};
          d["Value Prev"] = s["Bank Credit"];
          d["Growth"] = d["Bank Credit"] - d["Value Prev"];
          d["Growth Rate"] = ((d["Bank Credit"] - d["Value Prev"]) / d["Value Prev"]) * 100;
          delete d["Growth"]
          delete d["Value Prev"]
        });
    }

    const dataFinal = metricSelector === "value" ? data : data.filter(d => d["Growth Rate"])

    return dataFinal.map(d => ({
      [`${translations[time][locale]}`]: d[time],
      [`${translations["credits"][locale]}`]: d["Bank Credit"],
      [`${translations["growth"][locale]}`]: d["Growth Rate"],
