function customSort (a, b) {
    if (a["Economic Activity ID"]*1 === 25) return 1;
    if (b["Economic Activity ID"]*1 === 25) return -1;
    return b["Economic Activity"].localeCompare(a["Economic Activity"]);
}

const idDict = {
  "C": 3,
  "D": 4,
  "E": 5
};

const sectorID = idDict[variables.id];

