var id = variables.id;

var visibleHajj = id === "X"
var visibleUmrah = id === "Y"
var visibleTourism = id === "Z"

var visibleSectors = !visibleHajj && !visibleUmrah && !visibleTourism

//Real Sector Indicators
var gdpData = ["A", "B", "C", "D", "F", "G", "H", "K", "L", "N", "S"]
