var ipi =  ["B", "C", "D", "E"]
var visibleIPI = ipi.includes(id)

var ppi =  ["C", "D", "E"]
var visiblePPI = ppi.includes(id)

//Monetary
var pointOfSales = ["D", "F", "G", "H", "I", "J", "P", "Q", "R", "S"]
var visiblePointOfSales = pointOfSales.includes(id)

var paymentSystem = ["D", "H", "K", "N", "P", "R", "S"]
